    fn fresh(program: &Program) -> (ResolvedProgram, FunctionResolutionWork) {
        let (result, refused, _) = crate::bounded_output::with_limit_usage(LIMIT, || {
            resolve_with_function_reuse(program, None, None, None, None)
        });
        assert!(!refused);
        result.unwrap()
    }
