    ) -> (ResolvedProgram, FunctionResolutionWork) {
        let (result, refused, _) = crate::bounded_output::with_limit_usage(LIMIT, || {
            resolve_with_function_reuse(current, Some(previous), Some(old), Some(costs), None)
        });
