            "lexical completion cannot carry ownership or runtime storage",
        ));
    }
    match &expression.kind {
        ResolvedExprKind::LexicalExit {
            kind,
            target,
            value,
        } => {
            if !route {
                return Err(error(
                    "lexical exit crosses a value-evaluation or callable boundary",
                ));
            }
            match (kind, target, value) {
                (
                    crate::ast::LexicalExitKind::Return,
                    ControlTarget::Function(actual),
                    Some(operand),
                ) if actual == owner
                    && operand.ty == function.return_type
                    && operand.ty != ResolvedType::Never =>
                {
                    walk(
                        program,
                        function,
                        owner,
                        operand,
                        false,
                        nearest,
                        None,
                        depth + 1,
                        inspect,
                    )?;
                }
                (
                    crate::ast::LexicalExitKind::Break | crate::ast::LexicalExitKind::Continue,
                    ControlTarget::Loop {
                        owner: actual,
                        site,
                    },
                    None,
                ) if actual == owner && nearest == Some(site) => {}
                _ => {
                    return Err(error(
                        "lexical exit kind, value or exact nearest target is inconsistent",
                    ))
                }
            }
        }
        ResolvedExprKind::Block { statements, tail }
        | ResolvedExprKind::VecConstructor {
            statements, tail, ..
        } => {
            for (index, statement) in statements.iter().enumerate() {
                match statement {
                    ResolvedStatement::While {
                        condition, body, ..
                    } => {
                        if contains(body) {
                            return Err(error(
                                "legacy while cannot contain lexical exit authority",
                            ));
                        }
                        walk(
                            program,
                            function,
                            owner,
                            condition,
                            false,
                            nearest,
                            allowed,
                            depth + 1,
                            inspect,
                        )?;
                        walk(
                            program,
                            function,
                            owner,
                            body,
                            route,
                            Some(&condition.id),
                            allowed,
                            depth + 1,
                            inspect,
                        )?;
                    }
                    ResolvedStatement::LexicalWhile {
                        condition,
                        body,
                        latch,
                        ..
                    } => {
                        if !contains(body) {
                            return Err(error("lexical loop profile has no explicit exit"));
                        }
                        validate_latch(condition, body, latch)?;
                        walk(
                            program,
                            function,
                            owner,
                            condition,
                            false,
                            nearest,
                            allowed,
                            depth + 1,
                            inspect,
                        )?;
                        walk(
                            program,
                            function,
                            owner,
                            body,
                            route,
                            Some(&condition.id),
                            allowed,
                            depth + 1,
                            inspect,
                        )?;
                    }
                    ResolvedStatement::Let {
                        binding,
                        mutable,
                        value,
                        ..
                    } => {
                        if let Some(wrapper) = source_for_wrapper_with(program, value, inspect)? {
                            if *mutable
                                || binding.ty != value.ty
                                || binding.ownership != OwnershipMode::Value
                            {
                                return Err(error(
                                    "source-for wrapper discard binding is inconsistent",
                                ));
                            }
                            walk(
                                program,
                                function,
                                owner,
                                value,
                                route,
                                nearest,
                                Some(wrapper.authored_body),
                                depth + 1,
                                inspect,
                            )?;
                        } else {
                            let guard = contains(value)
                                && matches!(
                                    value.kind,
                                    ResolvedExprKind::If { .. } | ResolvedExprKind::Match { .. }
                                )
                                && !*mutable
                                && binding.ty == ResolvedType::I64
                                && binding.ownership == OwnershipMode::Value
                                && value.ty == binding.ty
                                && value.ownership == binding.ownership
                                && guard_completion(value, 0)
                                && statements[index + 1..].iter().all(|s| {
                                    (0..s.child_count()).all(|i| {
                                        s.child(i).is_none_or(|e| no_read(e, &binding.id, 0))
                                    })
                                })
                                && no_read(tail, &binding.id, 0);
                            if binding.ty == ResolvedType::Never
                                && !allowed.is_some_and(|a| std::ptr::eq(a, value))
                            {
                                return Err(error("lexical completion cannot initialize storage"));
                            }
                            walk(
                                program,
                                function,
                                owner,
                                value,
                                route && guard,
                                nearest,
                                allowed,
                                depth + 1,
                                inspect,
                            )?;
                        }
                    }
                    ResolvedStatement::CopyDiscard { value, .. } => {
                        super::super::copy_discard::require(value)?;
                        walk(
                            program,
                            function,
                            owner,
                            value,
                            route,
                            nearest,
                            allowed,
                            depth + 1,
                            inspect,
                        )?;
                    }
                    ResolvedStatement::Assign { value, .. } => walk(
                        program,
                        function,
                        owner,
                        value,
                        false,
                        nearest,
                        allowed,
                        depth + 1,
                        inspect,
                    )?,
                    ResolvedStatement::Unsafe { body, .. } => walk(
                        program,
                        function,
                        owner,
                        body,
                        false,
                        nearest,
                        None,
                        depth + 1,
                        inspect,
                    )?,
                }
            }
            walk(
                program,
                function,
                owner,
                tail,
                route,
                nearest,
                allowed,
                depth + 1,
                inspect,
            )?;
        }
        ResolvedExprKind::If {
            condition,
            then_branch,
            else_branch,
        } => {
            walk(
                program,
                function,
                owner,
                condition,
                false,
                nearest,
                allowed,
                depth + 1,
                inspect,
            )?;
            walk(
                program,
                function,
                owner,
                then_branch,
                route,
                nearest,
                allowed,
                depth + 1,
                inspect,
            )?;
            walk(
                program,
                function,
                owner,
                else_branch,
                route,
                nearest,
                allowed,
                depth + 1,
                inspect,
            )?;
        }
        ResolvedExprKind::Match {
            scrutinee, arms, ..
        } => {
            walk(
                program,
                function,
                owner,
                scrutinee,
                false,
                nearest,
                allowed,
                depth + 1,
                inspect,
            )?;
            for arm in arms {
                if let Some(guard) = &arm.guard {
                    walk(
                        program,
                        function,
                        owner,
                        guard,
                        false,
                        nearest,
                        None,
                        depth + 1,
                        inspect,
                    )?;
                }
                walk(
                    program,
                    function,
                    owner,
                    &arm.value,
                    route,
                    nearest,
                    allowed,
                    depth + 1,
                    inspect,
                )?;
            }
        }
        ResolvedExprKind::Closure { captures, body, .. } => {
            for capture in captures {
                walk(
                    program,
                    function,
                    owner,
                    &capture.value,
                    false,
                    nearest,
                    None,
                    depth + 1,
                    inspect,
                )?;
            }
            walk(
                program,
                function,
                owner,
                body,
                false,
                None,
                None,
                depth + 1,
                inspect,
            )?;
        }
        _ => {
            let mut index = 0;
            while let Some(next) = child(expression, index) {
                walk(
                    program,
                    function,
                    owner,
                    next,
                    false,
                    nearest,
                    allowed,
                    depth + 1,
                    inspect,
                )?;
                index += 1;
            }
        }
    }
    Ok(())
}

