mod tests;

//! Full ancestor freezes over every subtree, including nested lowered code.
//! Only borrowed lookup rows are sorted. No traversal skips an inner body.
use super::*;
use intervals::{Freeze, Kind};
#[derive(Clone, Copy)]
struct Receiver<'a> {
    expression: &'a ResolvedExpr,
}
pub(super) fn validate<'a>(
    function: &'a ResolvedFunction,
    rows: &[Row<'a>],
    index: &index::Index<'a>,
    declarations: Option<&DeclarationIndex>,
    storage: &Storage,
    walker: &mut Walker<'a>,
) -> Result<(), Failure> {
    let mut count = 0usize;
    for row in rows {
        let owner = owner(row, declarations)?;
        count = count
            .checked_add(7 + usize::from(owner.is_some()))
            .ok_or_else(|| Failure::semantic("borrowed byte traversal freeze count overflows"))?;
    }
    let mut freezes = storage.vector(count)?;
    let mut receivers = storage.vector(rows.len())?;
    let mut ancestors: Vec<usize> = storage.vector(rows.len())?;
    for (position, row) in rows.iter().enumerate() {
        while ancestors
            .last()
            .is_some_and(|parent| row.start >= rows[*parent].body_end)
        {
            ancestors.pop();
        }
        if ancestors.last().is_some_and(|parent| {
            row.start < rows[*parent].body_start || row.end > rows[*parent].body_end
        }) {
            return Err(Failure::semantic(
                "borrowed byte traversal region crosses its enclosing authored body",
            ));
        }
        let entry = ancestors
            .first()
            .map_or(row.start, |parent| rows[*parent].start);
        index.available(row.shape.view, entry)?;
        for id in row.shape.frozen {
            storage.push(
                &mut freezes,
                Freeze {
                    id,
                    kind: Kind::Rebind,
                    start: row.body_start,
                    end: row.body_end,
                    prefix_end: 0,
                },
            )?;
        }
        if let Some(id) = owner(row, declarations)? {
            storage.push(
                &mut freezes,
                Freeze {
                    id,
                    kind: Kind::Rebind,
                    start: row.body_start,
                    end: row.body_end,
                    prefix_end: 0,
                },
            )?;
        }
        storage.push(
            &mut freezes,
            Freeze {
                id: &row.shape.payload.id,
                kind: Kind::HiddenPayloadRead,
                start: row.body_start,
                end: row.body_end,
                prefix_end: 0,
            },
        )?;
        storage.push(
            &mut receivers,
            Receiver {
                expression: row.shape.receiver,
            },
        )?;
        storage.push(&mut ancestors, position)?;
    }
    intervals::prepare(&mut freezes);
    receivers.sort_unstable_by(|a, b| a.expression.id.cmp(&b.expression.id));
    let mut unauthorized = false;
    walker.function(function, |event| {
        let Event::Enter { expression, position } = event else { return Ok(()); };
        if matches!(&expression.kind, ResolvedExprKind::Place(place) | ResolvedExprKind::BorrowPlace { place, .. } if intervals::active(&freezes, &place.root, Kind::HiddenPayloadRead, position)) {
            return Err(Failure::semantic("borrowed byte receiver payload escapes its receiver"));
        }
        if let ResolvedExprKind::Block { statements, .. } | ResolvedExprKind::VecConstructor { statements, .. } = &expression.kind {
            for statement in statements {
                if let ResolvedStatement::Let { binding, .. } | ResolvedStatement::Assign { binding, .. } = statement {
                    if intervals::active(&freezes, &binding.id, Kind::Rebind, position) {
                        return Err(Failure::semantic("borrowed byte traversal view, owner, counter or item is mutated or rebound"));
                    }
                }
            }
        }
        if let ResolvedExprKind::Match { arms, .. } = &expression.kind {
            for arm in arms {
                if let ResolvedMatchPattern::Variant { fields, .. } = &arm.pattern {
                    if fields.iter().any(|field| intervals::active(&freezes, &field.binding.id, Kind::Rebind, position)) {
                        return Err(Failure::semantic("borrowed byte traversal binding is shadowed"));
                    }
                }
            }
        }
        if receiver_shape(expression).is_some() {
            let admitted = receivers.binary_search_by(|row| row.expression.id.cmp(&expression.id)).ok().is_some_and(|index| std::ptr::eq(receivers[index].expression, expression));
            unauthorized |= !admitted;
        }
        Ok(())
    })?;
    if unauthorized {
        return Err(Failure::semantic(
            "borrowed byte receiver is outside an authenticated Slice<u8> traversal",
        ));
    }
    Ok(())
}
fn owner<'a>(
    row: &Row<'_>,
    declarations: Option<&'a DeclarationIndex>,
) -> Result<Option<&'a ValueId>, Failure> {
    let Some(declarations) = declarations else {
        return Ok(None);
    };
    let view = bare_place(row.shape.view)
        .ok_or_else(|| Failure::semantic("borrowed byte traversal view is not a bare place"))?;
    let provenance = declarations
        .byte_slice_provenance(&view.root)
        .ok_or_else(|| {
            Failure::semantic(
                "borrowed byte traversal view lacks authenticated byte-slice provenance",
            )
        })?;
    Ok((provenance.root != view.root).then_some(&provenance.root))
}

//! Exact borrowed node/definition index. Sorting touches private lookup rows,
//! never HIR, cleanup vectors, or runtime evaluation order.
use super::*;
#[derive(Clone, Copy)]
pub(super) struct Node<'a> {
    pub(super) expression: &'a ResolvedExpr,
    pub(super) start: usize,
    pub(super) end: usize,
}
#[derive(Clone, Copy)]
pub(super) struct Definition<'a> {
    pub(super) id: &'a ValueId,
    pub(super) value: Option<&'a ResolvedExpr>,
    pub(super) mutable: bool,
    pub(super) ty: &'a ResolvedType,
}
pub(super) struct Index<'a> {
    nodes: Vec<Node<'a>>,
    definitions: Vec<Definition<'a>>,
    pub(super) regions: usize,
}
impl<'a> Index<'a> {
    pub(super) fn build(
        function: &'a ResolvedFunction,
        storage: &Storage,
        walker: &mut Walker<'a>,
    ) -> Result<Self, Failure> {
        storage
            .reserve(std::mem::size_of::<Self>() + std::mem::size_of::<Result<Self, Failure>>())?;
        let (mut nodes, mut definitions, mut regions) = (0usize, function.params.len(), 0usize);
        walker.function(function, |event| {
            if let Event::Enter { expression, .. } = event {
                nodes = nodes.checked_add(1).ok_or_else(|| {
                    Failure::semantic("borrowed byte traversal census node count overflows")
                })?;
                if shape::shape(expression)?.is_some() {
                    regions = regions.checked_add(1).ok_or_else(|| {
                        Failure::semantic("borrowed byte traversal census region count overflows")
                    })?;
                }
                if let ResolvedExprKind::Block { statements, .. }
                | ResolvedExprKind::VecConstructor { statements, .. } = &expression.kind
                {
                    definitions = definitions
                        .checked_add(
                            statements
                                .iter()
                                .filter(|statement| {
                                    matches!(statement, ResolvedStatement::Let { .. })
                                })
                                .count(),
                        )
                        .ok_or_else(|| {
                            Failure::semantic(
                                "borrowed byte traversal census binding count overflows",
                            )
                        })?;
                }
            }
            Ok(())
        })?;
        if regions < 2 {
            return Err(Failure::semantic(
                "borrowed byte traversal is nested in another traversal",
            ));
        }
        let mut result = Self {
            nodes: storage.vector(nodes)?,
            definitions: storage.vector(definitions)?,
            regions,
        };
        for parameter in &function.params {
            storage.push(
                &mut result.definitions,
                Definition {
                    id: &parameter.id,
                    value: None,
                    mutable: false,
                    ty: &parameter.ty,
                },
            )?;
        }
        walker.function(function, |event| {
            match event {
                Event::Enter {
                    expression,
                    position,
                } => {
                    storage.push(
                        &mut result.nodes,
                        Node {
                            expression,
                            start: position,
                            end: 0,
                        },
                    )?;
                    if let ResolvedExprKind::Block { statements, .. }
                    | ResolvedExprKind::VecConstructor { statements, .. } = &expression.kind
                    {
                        for statement in statements {
                            if let ResolvedStatement::Let {
                                binding,
                                mutable,
                                value,
                                ..
                            } = statement
                            {
                                storage.push(
                                    &mut result.definitions,
                                    Definition {
                                        id: &binding.id,
                                        value: Some(value),
                                        mutable: *mutable,
                                        ty: &binding.ty,
                                    },
                                )?;
                            }
                        }
                    }
                }
                Event::Exit { position, end, .. } => result.nodes[position].end = end,
            }
            Ok(())
        })?;
        result
            .nodes
            .sort_unstable_by(|a, b| a.expression.id.cmp(&b.expression.id));
        if result
            .nodes
            .windows(2)
            .any(|pair| pair[0].expression.id == pair[1].expression.id)
        {
            return Err(Failure::semantic(
                "borrowed byte traversal census has duplicate expression identity",
            ));
        }
        result.definitions.sort_unstable_by(|a, b| a.id.cmp(b.id));
        if result
            .definitions
            .windows(2)
            .any(|pair| pair[0].id == pair[1].id)
        {
            return Err(Failure::semantic(
                "borrowed byte traversal census has duplicate binding identity",
            ));
        }
        Ok(result)
    }
    pub(super) fn node(&self, expression: &ResolvedExpr) -> Result<Node<'a>, Failure> {
        let node = self
            .nodes
            .binary_search_by(|row| row.expression.id.cmp(&expression.id))
            .ok()
            .map(|index| self.nodes[index]);
        node.filter(|node| std::ptr::eq(node.expression, expression))
            .ok_or_else(|| {
                Failure::semantic(
                    "borrowed byte traversal census expression differs from current function",
                )
            })
    }
    pub(super) fn available(&self, view: &ResolvedExpr, before: usize) -> Result<(), Failure> {
        let place = bare_place(view)
            .ok_or_else(|| Failure::semantic("borrowed byte traversal view is not a bare place"))?;
        let definition = self
            .definitions
            .binary_search_by(|row| row.id.cmp(&place.root))
            .ok()
            .map(|index| self.definitions[index])
            .ok_or_else(|| {
                Failure::semantic(
                    "nested borrowed byte traversal view is not bound at outermost entry",
                )
            })?;
        if definition.mutable
            || *definition.ty != ResolvedType::SliceU8
            || definition
                .value
                .is_some_and(|value| self.node(value).map_or(true, |node| node.end > before))
        {
            return Err(Failure::semantic(
                "nested borrowed byte traversal view is not immutable at outermost entry",
            ));
        }
        Ok(())
    }
}

//! Private lookup rows, never canonical HIR/cleanup vectors. A sorted prefix
//! maximum keeps an outer freeze active after a nested same-root freeze ends.
//! These functions lend no admission or payer; the authenticated producer owns
//! and prepays every row, and validates the exact function/region on lookup.
use crate::hir::ValueId;

#[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]
pub(super) enum Kind {
    Rebind,
    HiddenPayloadRead,
}
#[derive(Clone, Copy)]
pub(super) struct Freeze<'a> {
    pub(super) id: &'a ValueId,
    pub(super) kind: Kind,
    pub(super) start: usize,
    pub(super) end: usize,
    pub(super) prefix_end: usize,
}
pub(super) fn prepare(rows: &mut [Freeze<'_>]) {
    rows.sort_unstable_by(|a, b| {
        a.id.cmp(b.id)
            .then(a.kind.cmp(&b.kind))
            .then(a.start.cmp(&b.start))
    });
    let mut previous: Option<(&ValueId, Kind)> = None;
    let mut end = 0;
    for row in rows {
        let key = (row.id, row.kind);
        if previous != Some(key) {
            end = 0;
        }
        end = end.max(row.end);
        row.prefix_end = end;
        previous = Some(key);
    }
}
pub(super) fn active(rows: &[Freeze<'_>], id: &ValueId, kind: Kind, position: usize) -> bool {
    let next = rows.partition_point(|row| {
        row.id < id
            || (row.id == id && (row.kind < kind || (row.kind == kind && row.start <= position)))
    });
    next.checked_sub(1).is_some_and(|previous| {
        let row = &rows[previous];
        row.id == id && row.kind == kind && position < row.prefix_end
    })
}

//! Local receiver structure only; never a complete provenance/owner verdict.
//! Contextual census must independently freeze every enclosing region.
use super::super::*;

#[derive(Clone, Copy)]
pub(super) struct Shape<'a> {
    pub(super) root: &'a ResolvedExpr,
    pub(super) receiver: &'a ResolvedExpr,
    pub(super) authored_body: &'a ResolvedExpr,
    pub(super) view: &'a ResolvedExpr,
    pub(super) payload: &'a ResolvedBinding,
    pub(super) frozen: [&'a ValueId; 6],
}
fn fail(message: &'static str) -> Diagnostic {
    Diagnostic::io_static("SPX-H006", message)
}
pub(super) fn shape(region: &ResolvedExpr) -> Result<Option<Shape<'_>>, Diagnostic> {
    let ResolvedExprKind::Block { statements, tail } = &region.kind else {
        return Ok(None);
    };
    let [ResolvedStatement::Let {
        binding: length,
        mutable: false,
        value: count,
        ..
    }, ResolvedStatement::Let {
        binding: counter,
        mutable: true,
        value: seed,
        ..
    }, looped] = statements.as_slice()
    else {
        return Ok(None);
    };
    let ResolvedExprKind::Call {
        callee,
        type_arguments,
        instance: None,
        args,
    } = &count.kind
    else {
        return Ok(None);
    };
    if callee.as_str() != crate::byte_ops::LEN_ID {
        return Ok(None);
    }
    let (condition, body, latch) = match looped {
        ResolvedStatement::While {
            condition, body, ..
        } => (condition, body, None),
        ResolvedStatement::LexicalWhile {
            condition,
            body,
            latch,
            ..
        } => (condition, body, Some(latch)),
        _ => return Ok(None),
    };
    let ResolvedExprKind::Block {
        statements: steps,
        tail: step_tail,
    } = &body.kind
    else {
        return Ok(None);
    };
    let [ResolvedStatement::Let {
        binding: item,
        mutable: false,
        value: read,
        ..
    }, ResolvedStatement::Let {
        binding: discard,
        mutable: false,
        value: authored_body,
        ..
    }, ResolvedStatement::Assign {
        binding: assigned,
        field: None,
        value: advance,
        ..
    }] = steps.as_slice()
    else {
        return Ok(None);
    };
    let Some(proof) = receiver_shape(read) else {
        return Ok(None);
    };
    let inconsistent = || fail("borrowed byte traversal differs from its authenticated lowering");
    let [view] = args.as_slice() else {
        return Err(inconsistent());
    };
    let ResolvedExprKind::Binary {
        op: crate::ast::BinaryOp::Lt,
        left,
        right,
    } = &condition.kind
    else {
        return Err(inconsistent());
    };
    let ResolvedExprKind::Binary {
        op: crate::ast::BinaryOp::Add,
        left: old,
        right: one,
    } = &advance.kind
    else {
        return Err(inconsistent());
    };
    let Some(view_place) = bare_place(view) else {
        return Err(inconsistent());
    };
    if !type_arguments.is_empty()
        || view.ty != ResolvedType::SliceU8
        || proof.view.ty != view.ty
        || proof.view.ownership != view.ownership
        || bare_place(proof.view) != Some(view_place)
        || count.ty != ResolvedType::Usize
        || count.ownership != OwnershipMode::Value
        || length.ty != ResolvedType::Usize
        || length.ownership != OwnershipMode::Value
        || counter.ty != ResolvedType::Usize
        || counter.ownership != OwnershipMode::Value
        || !zero(seed)
        || !zero(tail)
        || region.ty != ResolvedType::Usize
        || region.ownership != OwnershipMode::Value
        || condition.ty != ResolvedType::Bool
        || condition.ownership != OwnershipMode::Value
        || !place_of(left, counter)
        || !place_of(right, length)
        || !place_of(proof.index, counter)
        || item.ty != ResolvedType::U8
        || item.ownership != OwnershipMode::Value
        || discard.ty != authored_body.ty
        || discard.ownership != authored_body.ownership
        || assigned.id != counter.id
        || assigned.ty != counter.ty
        || advance.ty != ResolvedType::Usize
        || advance.ownership != OwnershipMode::Value
        || !place_of(old, counter)
        || !matches!(one.kind, ResolvedExprKind::Usize(1))
        || one.ty != ResolvedType::Usize
        || one.ownership != OwnershipMode::Value
        || !zero(step_tail)
    {
        return Err(inconsistent());
    }
    if let Some(latch) = latch {
        if !matches!(latch, LoopLatchKind::SourceForStep { kind: SourceForKind::BorrowBytes, step } if step == &advance.id)
        {
            return Err(inconsistent());
        }
    }
    Ok(Some(Shape {
        root: region,
        frozen: [
            &length.id,
            &counter.id,
            &item.id,
            &discard.id,
            &proof.payload.id,
            &view_place.root,
        ],
        receiver: read,
        authored_body,
        view,
        payload: proof.payload,
    }))
}

//! A paid receiving carrier lazily holds one independently replayed census.
//! Selection reuses the existing complete v1 region check; it creates no extra
//! cursor scan, temporary owned error text or unpriced selector workspace.
use super::*;
pub(crate) struct Slot<'a> {
    context: &'a dyn crate::cleanup::ReplayContext,
    function: &'a ResolvedFunction,
    proof: Option<Census<'a>>,
    storage: Storage,
}
pub(crate) fn controls(bytes: usize) -> Result<(), Diagnostic> {
    if crate::bounded_output::active_remaining().is_some() {
        #[cfg(test)]
        super::tests::record_request(bytes);
        if !crate::bounded_output::reserve_active_required(bytes) {
            #[cfg(test)]
            super::tests::record_failure();
            return Err(Failure::Storage(Refused::Budget).diagnostic());
        }
    }
    Ok(())
}
impl<'a> Slot<'a> {
    pub(crate) fn new(
        context: &'a dyn crate::cleanup::ReplayContext,
        function: &'a ResolvedFunction,
    ) -> Result<Self, Diagnostic> {
        let storage = Storage::acquire().map_err(|error| Failure::Storage(error).diagnostic())?;
        storage
            .reserve(std::mem::size_of::<Self>() + std::mem::size_of::<Result<Self, Diagnostic>>())
            .map_err(|error| Failure::Storage(error).diagnostic())?;
        Ok(Self {
            context,
            function,
            proof: None,
            storage,
        })
    }
    pub(crate) fn region(
        &mut self,
        context: &dyn crate::cleanup::ReplayContext,
        function: &'a ResolvedFunction,
        expression: &'a ResolvedExpr,
    ) -> Result<Option<Region<'a>>, Diagnostic> {
        self.storage
            .reserve(0)
            .map_err(|error| Failure::Storage(error).diagnostic())?;
        if !std::ptr::eq(context, self.context) || !std::ptr::eq(function, self.function) {
            return Err(Failure::semantic(
                "borrowed byte traversal census function differs from its current receiver",
            )
            .diagnostic());
        }
        if let Some(proof) = &self.proof {
            return proof.region(context, function, expression);
        }
        match super::super::region(expression) {
            Err(error) if nested_refusal(&error) => {
                let proof = Census::acquire(self.context, self.function)?;
                let region = proof.region(context, function, expression)?;
                self.proof = Some(proof);
                Ok(region)
            }
            original => original,
        }
    }
    pub(crate) fn region_for(
        &mut self,
        context: &dyn crate::cleanup::ReplayContext,
        expression: &'a ResolvedExpr,
    ) -> Result<Option<Region<'a>>, Diagnostic> {
        self.region(context, self.function, expression)
    }
}
pub(in crate::hir) fn nested_refusal(error: &Diagnostic) -> bool {
    error.code == "SPX-H006"
        && error.message == "borrowed byte traversal is nested in another traversal"
}

//! Exact current-invocation storage; None ACTIVE retains the explicit ordinary
//! unobserved API policy and is never described as funded. No quota is created.
use crate::bounded_output::classifier_string::ClassifierLedger;
use crate::bounded_output::{active_remaining, refuse_active_required, reserve_active_required};
use std::alloc::Layout;
use std::cell::Cell;
use std::mem::size_of;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(in crate::hir::validation::byte_traversal) enum Refused {
    Budget,
    Detached,
    Layout,
    Allocation,
    Capacity,
}
pub(super) struct Storage {
    ledger: ClassifierLedger,
    observed: bool,
    first: Cell<Option<Refused>>,
}
impl Storage {
    pub(super) fn acquire() -> Result<Self, Refused> {
        let observed = active_remaining().is_some();
        let bytes = size_of::<Self>() + size_of::<Result<Self, Refused>>();
        #[cfg(test)]
        if observed {
            super::tests::record_request(bytes);
        }
