    let ast = crate::check(SOURCE, "nested-bytes.spx").unwrap();
    let canonical = crate::format::canonical(&ast);
    assert_eq!(
        crate::format::canonical(&crate::check(&canonical, "nested-bytes.spx").unwrap()),
        canonical
