#[test]
fn nested_byte_while_bridge_and_inner_only_exits_replay_exact_nearest_targets() {
    let program = resolved(SOURCE);
    for name in ["exits", "while_bridge"] {
        let function = function(&program, name);
        let owner = FunctionExecutionId::Monomorphic(function.id.clone());
        crate::hir::lexical_exit::validate_function(&program, function, &owner).unwrap();
        assert!(Census::acquire(&program, function).is_ok());
    }
    let mut forged = program.clone();
    let exits = forged
        .functions
        .iter_mut()
        .find(|function| function.name == "exits")
        .unwrap();
    let region = super::tests::outer(exits);
    let ResolvedExprKind::Block { statements, .. } = &region.kind else {
        panic!("outer region")
    };
    let (ResolvedStatement::While { condition, .. }
    | ResolvedStatement::LexicalWhile { condition, .. }) = &statements[2]
    else {
        panic!("outer loop")
    };
    let site = condition.id.clone();
    assert_eq!(
        retarget(region, &site),
        2,
        "both inner Break/Continue are kept"
    );
    let exits = function(&forged, "exits");
    let owner = FunctionExecutionId::Monomorphic(exits.id.clone());
    let error = crate::hir::lexical_exit::validate_function(&forged, exits, &owner).unwrap_err();
    assert_eq!(
        error,
        Diagnostic::io(
            "SPX-H006",
            "lexical exit kind, value or exact nearest target is inconsistent"
        )
    );
    assert!(crate::hir::validate(&forged).is_err());
    // An ordinary Vec accumulator is unrelated to byte receiver authority.
    // Source-for nesting remains closed for Vec; ordinary safe primitives do not.
    let accumulated = SOURCE.replacen("let mut total = 0;", "let mut total = 0; let mut accumulated = vec_with_capacity<i64>(6usize);", 1)
        .replacen("for inner in right { total", "for inner in right { accumulated = vec_push<i64>(accumulated, i64_from_u8(inner)); total", 1);
    let accumulated = resolved(&accumulated);
    super::super::validate_function(&accumulated.declarations, function(&accumulated, "sum"))
        .unwrap();
}
#[test]
fn nested_byte_same_root_release_does_not_allow_outer_move_or_renewal() {
    resolved(ROOTED);
    for source in [
        ROOTED.replace("let first=outer;", "let first=outer; let stolen=owned;"),
        ROOTED.replace(
            "let first=outer;",
            "let first=outer; owned=bytes_copy(array_as_slice(data));",
        ),
        ROOTED
            .replace("for outer in whole", "for outer in view")
            .replace("for inner in view", "for inner in whole")
            .replace("let first=outer;", "let first=outer; let stolen=owned;"),
    ] {
        let ast = crate::parse(&source, "nested-freeze.spx").unwrap();
        let diagnostics = crate::verify::verify(&ast);
        assert!(
            diagnostics.iter().any(|error| error.code == "SPX-T265"),
            "{diagnostics:?}"
        );
        assert!(crate::hir::resolve(&ast).is_err());
    }
}

//! One preowned iterative cursor stack, reused by census passes and roots.
//! Closures lend evaluated captures only, exactly as the original census.
use super::{Failure, Storage};
use crate::hir::{ResolvedExpr, ResolvedExprKind, ResolvedFunction};
use std::mem::size_of;

#[derive(Clone, Copy)]
struct Frame<'a> {
    cursor: crate::hir::lexical_exit::ChildCursor<'a>,
    capture: usize,
    entered: bool,
    position: usize,
}
#[derive(Clone, Copy)]
pub(super) enum Event<'a> {
    Enter {
        expression: &'a ResolvedExpr,
        position: usize,
    },
    Exit {
        _expression: &'a ResolvedExpr,
        position: usize,
        end: usize,
    },
}
pub(super) struct Walker<'a> {
    frames: [Option<Frame<'a>>; crate::cache_codec::MAX_DEPTH + 1],
}
impl<'a> Walker<'a> {
    pub(super) fn acquire(storage: &Storage) -> Result<Self, Failure> {
        storage.reserve(size_of::<Self>() + size_of::<Result<Self, Failure>>())?;
        Ok(Self {
            frames: [None; crate::cache_codec::MAX_DEPTH + 1],
        })
    }
    pub(super) fn function(
        &mut self,
        function: &'a ResolvedFunction,
        mut visit: impl FnMut(Event<'a>) -> Result<(), Failure>,
    ) -> Result<(), Failure> {
        let mut ordinal = 0usize;
        for root in function
            .ensures
            .iter()
            .rev()
            .chain(std::iter::once(&function.body))
            .chain(function.requires.iter().rev())
        {
            self.root(root, &mut ordinal, &mut visit)?;
        }
        Ok(())
    }
    fn root(
        &mut self,
        root: &'a ResolvedExpr,
        ordinal: &mut usize,
        visit: &mut impl FnMut(Event<'a>) -> Result<(), Failure>,
    ) -> Result<(), Failure> {
        // A prior failed/finished pass cannot leave authorization or a cursor
        // in the next root. Clearing only borrowed Copy rows cannot allocate.
        self.frames.fill(None);
        let frame = |expression| Frame {
            cursor: crate::hir::lexical_exit::ChildCursor::new(expression),
            capture: 0,
            entered: false,
            position: 0,
        };
        self.frames[0] = Some(frame(root));
        let mut len = 1;
        while len != 0 {
            let current = self.frames[len - 1]
                .as_mut()
                .expect("occupied census frame");
            let expression = current.cursor.expression();
            if !current.entered {
                current.position = *ordinal;
                *ordinal = ordinal.checked_add(1).ok_or_else(|| {
                    Failure::semantic("borrowed byte traversal census identity count overflows")
                })?;
                visit(Event::Enter {
                    expression,
                    position: current.position,
                })?;
                current.entered = true;
            }
            let next = if let ResolvedExprKind::Closure { captures, .. } = &expression.kind {
                let next = captures.get(current.capture).map(|capture| &capture.value);
                current.capture += usize::from(next.is_some());
                next
            } else {
                current.cursor.next()
            };
            if let Some(next) = next {
                if len == self.frames.len() {
                    return Err(Failure::semantic(
                        "borrowed byte traversal scan exceeds admitted expression depth",
                    ));
                }
                self.frames[len] = Some(frame(next));
                len += 1;
            } else {
                visit(Event::Exit {
                    _expression: expression,
                    position: current.position,
                    end: *ordinal,
                })?;
                len -= 1;
                self.frames[len] = None;
            }
        }
        Ok(())
    }
}

