        // Recompute edge proof only for a previously rejected terminal shape.
        (edge_live, termination_edges) = paid_live::dense::edge_liveness(&cfg, &live, work)?;
    }
    paid_materialize::materialize(
        cfg,
        drafts,
        parents,
        edge_live,
        termination_edges,
        payer.expect("private funded entry"),
    )
}

