        origin_span: proof.source.span,
        parent_root: None,
        binding: None,
        start: cfg.node(proof.region, LoanPointPhase::Before)?,
        seeds: [cfg.node(proof.region, LoanPointPhase::After)?]
            .into_iter()
            .collect(),
        cause: LoanCause::TraversalFreeze,
    }))
}

