        matches!(&advance.kind, ResolvedExprKind::Binary { op: BinaryOp::Add, right, .. }
        if matches!(right.kind, ResolvedExprKind::Usize(1)))
    );

    // The receiver is the existing Option<u8> result with exactly one arm.
    let ResolvedExprKind::Match {
        mode: hir::ResolvedMatchMode::Value,
        scrutinee,
        arms,
    } = &read.kind
    else {
        panic!("byte receiver")
    };
    assert_eq!(read.ty, ResolvedType::U8);
    let ResolvedExprKind::Call { callee, args, .. } = &scrutinee.kind else {
        panic!("byte_get")
    };
    assert_eq!(callee.as_str(), "core.bytes.get");
    assert_eq!(place_root(&args[0]), view_root);
    assert_eq!(place_root(&args[1]), &counter.id);
    let [arm] = arms.as_slice() else {
        panic!("only Some selects")
    };
    assert!(arm.guard.is_none());
    let hir::ResolvedMatchPattern::Variant { case, fields, .. } = &arm.pattern else {
        panic!("Some pattern")
    };
    assert_eq!(case.as_str(), "core.option.some");
    assert_eq!(place_root(&arm.value), &fields[0].binding.id);

    // No buffer, copy or view is materialized by the lowering itself. The
    // receiver adds exactly two identities to the Vec form's sixteen; the
    // workspace prebound keeps sixteen and the byte lowering debits the rest.
    assert_eq!(synthesized(wrapper(&resolved, "sum"), &authored.id), 18);

    // Lexical exits keep the latch on the exact unit step.
    let ResolvedExprKind::Block { statements, .. } = &wrapper(&resolved, "exits").kind else {
        panic!("wrapper block")
    };
    let ResolvedStatement::LexicalWhile { body, latch, .. } = &statements[2] else {
        panic!("lexical traversal loop")
    };
    let ResolvedExprKind::Block { statements, .. } = &body.kind else {
        panic!("loop body")
    };
    let ResolvedStatement::Assign { value: step, .. } = &statements[2] else {
        panic!("unit step")
    };
    assert_eq!(
        latch,
        &hir::LoopLatchKind::SourceForStep {
            kind: hir::SourceForKind::BorrowBytes,
            step: step.id.clone(),
        }
    );

    let rendered = graph::to_json(&program).unwrap();
    graph::verify_json(&program, &rendered).unwrap();
    let compact =
        serde_json::to_string(&serde_json::from_str::<serde_json::Value>(&rendered).unwrap())
            .unwrap();
    assert!(compact.contains("core.bytes.get"));
    assert!(compact.contains("\"source_kind\":\"borrow_bytes\""));
    // Only the receivers select a single case; the manual oracle stays exhaustive.
    assert!(compact.contains("\"exhaustive\":false"));
    assert!(compact.contains("\"exhaustive\":true"));
    // Graph v83 owns these additive spellings.
    let document: serde_json::Value = serde_json::from_str(&rendered).unwrap();
    assert_eq!(document["schema"], "semaprax.graph.v83");
    let forged = rendered.replacen("semaprax.graph.v83", "semaprax.graph.v81", 1);
    assert!(graph::verify_json(&program, &forged).is_err());

    // A Vec traversal keeps its prior schema and spells none of them.
    let vec_program = parsed(
        "module app.vec_traversal;\n\n@id(\"app.vec.main\")\nfn main() -> i64 {\n    let values = vec_push<i64>(vec_with_capacity<i64>(1usize), 7);\n    let mut total = 0;\n    for value in values { total = total + value; 0 }\n    total\n}\n",
    );
    let vec_graph = graph::to_json(&vec_program).unwrap();
    assert!(!vec_graph.contains("semaprax.graph.v83"));
    assert!(!vec_graph.contains("borrow_bytes"));
    assert!(!vec_graph.contains("\"exhaustive\":false"));
}

#[test]
fn hostile_byte_traversal_hir_is_refused_independently_of_its_spelling() {
    let original = checked();
    let refuse = |program: hir::ResolvedProgram, case: &str| {
        let error = hir::validate(&program).expect_err(case);
        assert!(error.code.starts_with("SPX-H"), "{case}: {error:?}");
    };

    let mut forged = original.clone();
    let (_, latch) = loop_steps(wrapper_statements(&mut forged, "exits"));
    let Some(hir::LoopLatchKind::SourceForStep { kind, .. }) = latch else {
        panic!("byte latch")
    };
    *kind = hir::SourceForKind::Copy;
    refuse(forged, "Copy latch over a byte receiver");

    let mut forged = original.clone();
    let (steps, latch) = loop_steps(wrapper_statements(&mut forged, "exits"));
    let read = steps[0].value().id.clone();
    let Some(hir::LoopLatchKind::SourceForStep { step, .. }) = latch else {
        panic!("byte latch")
    };
    *step = read;
    refuse(forged, "latch step detached from the unit advance");

    let mut forged = original.clone();
    let statements = wrapper_statements(&mut forged, "sum");
    let length = statements[0].binding().id.clone();
    let (steps, _) = loop_steps(statements);
    let ResolvedStatement::Let { value: read, .. } = &mut steps[0] else {
        panic!("item")
    };
    let ResolvedExprKind::Match { scrutinee, .. } = &mut read.kind else {
        panic!("receiver")
    };
    let ResolvedExprKind::Call { args, .. } = &mut scrutinee.kind else {
        panic!("byte_get")
    };
    args[1].kind = ResolvedExprKind::Place(hir::Place {
        root: length,
        projections: Vec::new(),
    });
    refuse(forged, "receiver index forged to the snapshot");

    let mut forged = original.clone();
    let statements = wrapper_statements(&mut forged, "sum");
    let ResolvedStatement::Let { value: seed, .. } = &mut statements[1] else {
        panic!("seed")
    };
    seed.kind = ResolvedExprKind::Usize(1);
    refuse(forged, "skipped first element");

    let mut forged = original.clone();
    let (steps, _) = loop_steps(wrapper_statements(&mut forged, "sum"));
    let ResolvedStatement::Assign { value: advance, .. } = &mut steps[2] else {
        panic!("advance")
    };
    let ResolvedExprKind::Binary { right, .. } = &mut advance.kind else {
        panic!("unit step")
    };
    right.kind = ResolvedExprKind::Usize(2);
    refuse(forged, "skipped alternate elements");

    let mut forged = original.clone();
    let (steps, _) = loop_steps(wrapper_statements(&mut forged, "exits"));
    let ResolvedStatement::Let { value: read, .. } = &mut steps[0] else {
        panic!("item")
    };
    let ResolvedExprKind::Match { arms, .. } = &mut read.kind else {
        panic!("receiver")
    };
    let mut none = arms[0].clone();
    none.pattern = hir::ResolvedMatchPattern::Variant {
        variant: hir::DeclarationId::new("core.option"),
        case: hir::DeclarationId::new("core.option.none"),
        fields: Vec::new(),
    };
    none.value.kind = ResolvedExprKind::Uint8(0);
    arms.push(none);
    refuse(forged, "default-zero None arm under the byte latch");

    let mut forged = original.clone();
    let statements = wrapper_statements(&mut forged, "sum");
    let ResolvedStatement::Let { value: count, .. } = &mut statements[0] else {
        panic!("snapshot")
    };
    let ResolvedExprKind::Call { callee, .. } = &mut count.kind else {
        panic!("byte_len")
    };
    *callee = hir::DeclarationId::new("core.vec.len");
    refuse(forged, "receiver detached from its authenticated region");

    let mut forged = original.clone();
    let statements = wrapper_statements(&mut forged, "sum");
    let counter = statements[1].binding().clone();
    let (steps, _) = loop_steps(statements);
    let ResolvedStatement::Let {
        value: authored, ..
    } = &mut steps[1]
    else {
        panic!("authored body")
    };
    let ResolvedExprKind::Block { statements, .. } = &mut authored.kind else {
        panic!("authored block")
    };
    let ResolvedStatement::Assign { binding, value, .. } = &mut statements[0] else {
        panic!("authored assignment")
    };
    *binding = counter;
    value.kind = ResolvedExprKind::Usize(0);
    value.ty = ResolvedType::Usize;
    refuse(forged, "authored body rewinds the hidden counter");
}

#[test]
fn byte_for_refusals_and_owner_freeze_are_stable() {
    let baseline = parsed(REFUSAL);
    assert!(verify::verify(&baseline).is_empty());
    hir::validate(&hir::resolve(&baseline).unwrap()).unwrap();

    let codes = |source: String| -> Vec<&'static str> {
        verify::verify(&parsed(&source))
            .iter()
            .map(|diagnostic| diagnostic.code)
            .collect()
    };

    let computed = REFUSAL.replacen("for byte in view", "for byte in bytes_as_slice(owned)", 1);
    assert!(codes(computed).contains(&"SPX-T284"));

    let mutable = REFUSAL.replacen("let view = ", "let mut view = ", 1);
    assert!(codes(mutable.clone()).contains(&"SPX-T284"));
    assert!(hir::resolve(&parsed(&mutable)).is_err());

    let reassigned = REFUSAL.replacen("let first = byte;", "byte = 0u8;", 1);
    assert!(codes(reassigned).contains(&"SPX-U101"));

    let shadowed = REFUSAL.replacen(
        "let mut total = 0;",
        "let mut total = 0; let byte = 1u8;",
        1,
    );
    let shadowed_codes = codes(shadowed.clone());
    assert!(shadowed_codes.contains(&"SPX-T209"));
    assert!(hir::resolve(&parsed(&shadowed)).is_err());

    let nested = REFUSAL.replacen(
        "let first = byte;",
        "for inner in view { let copy = inner; 0 } let first = byte;",
        1,
    );
    assert!(codes(nested).contains(&"SPX-T284"));

    // The body never names the view, so its alias loan alone could expire;
    // the traversal freeze keeps the owner unavailable for every iteration.
    let moved = REFUSAL.replacen(
        "let first = byte;",
        "let first = byte; let stolen = owned;",
        1,
    );
    assert!(codes(moved).contains(&"SPX-T265"));

    let renewed = REFUSAL
        .replacen("let owned = ", "let mut owned = ", 1)
        .replacen(
            "let first = byte;",
            "let first = byte; owned = bytes_copy(array_as_slice(data));",
            1,
        );
    assert!(codes(renewed).contains(&"SPX-T265"));

    let subrange = REFUSAL
        .replacen(
            "let view = bytes_as_slice(owned);",
            "let whole = bytes_as_slice(owned); let view = byte_range(whole, 0usize, 1usize);",
            1,
        )
        .replacen(
            "let first = byte;",
            "let first = byte; let stolen = owned;",
            1,
        );
    assert!(codes(subrange).contains(&"SPX-T265"));
}

edits.new:
//! Immutable borrowed `Slice<u8>` traversal against an independent manual
//! `byte_len`/`byte_get` loop and a Rust oracle on the interpreter, native
//! C11 `-O0`/`-O2` and Core-Wasm: empty, singleton, all 256 bytes, a
//! subrange, an owned buffer and a String root; `continue`, `break`, `return`,
//! lazy operands and a body failure that keeps its selected status.
use std::path::Path;
use std::process::Command;

use semaprax::{codegen, hir, interpreter, parse};

const SOURCE: &str = include_str!("../fixtures/byte-slice-traversal.spx");

const FAILURE: &str = r#"module app.byte_traversal_failure;

@id("app.failure.reject")
fn reject(byte: u8) -> i64
    requires byte != 9u8
{
    i64_from_u8(byte)
}

@id("app.main")
fn main() -> i64 {
    let data = [1u8, 9u8, 2u8];
    let owned = bytes_copy(array_as_slice(data));
    let view = bytes_as_slice(owned);
    let mut total = 0;
    for byte in view { total = total + reject(byte); 0 }
    total
}
"#;

/// A traversal-only module: parameter and array views, no owned buffer.
const VIEW_ONLY: &str = r#"module app.byte_traversal_view_only;

@id("app.view.sum")
fn sum(view: borrow Slice<u8>) -> i64 {
    let mut total = 0;
    for byte in view { total = total + i64_from_u8(byte); 0 }
    total
}

@id("app.main")
fn main() -> i64 {
    let data = [1u8, 2u8, 3u8];
    sum(array_as_slice(data))
}
"#;

fn mix(total: i64, byte: u8) -> i64 {
    (total * 31 + i64::from(byte)) % 1_000_000_007
}

fn fold(bytes: &[u8]) -> i64 {
    bytes.iter().fold(0, |total, byte| mix(total, *byte))
}

fn expected() -> i64 {
    let all = (0..=255u8).collect::<Vec<_>>();
    let cases: [&[u8]; 6] = [&[], &[7], &all, &all[10..20], &all, b"SEMAPRAX"];
    let whole = cases.iter().map(|bytes| fold(bytes)).sum::<i64>();
    let mut early = 0;
    for &byte in &all {
        if byte == 3 {
            continue;
        }
        if byte == 250 {
            break;
        }
        early = mix(early, byte);
    }
    let located = 200 + -1;
    let lazy = 1;
    whole * 2 + early * 2 + located + lazy + fold(&[6, 7])
}

#[test]
fn byte_for_matches_manual_loop_and_oracle_on_every_engine() {
    let expected = expected();
    let program = parse(SOURCE, Path::new("byte-slice-traversal.spx")).unwrap();
    hir::validate(&hir::resolve(&program).unwrap()).unwrap();
    let failure = parse(FAILURE, Path::new("byte-slice-traversal-failure.spx")).unwrap();
    hir::validate(&hir::resolve(&failure).unwrap()).unwrap();

    let root = std::env::temp_dir().join(format!("semaprax-byte-slice-for-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();
    let success_source = root.join("success.spx");
    let failure_source = root.join("failure.spx");
    std::fs::write(&success_source, SOURCE).unwrap();
    std::fs::write(&failure_source, FAILURE).unwrap();

    for _ in 0..4 {
        let outcome = interpreter::interpret(
            &success_source,
            "app.main",
            &[],
            &interpreter::InterpreterOptions::default(),
        )
        .unwrap();
        assert!(outcome.returned, "{}", outcome.envelope);
        assert!(
            outcome
                .envelope
                .contains(&format!("\"value\":\"{expected}\"")),
            "{}",
            outcome.envelope
        );
        let failed = interpreter::interpret(
            &failure_source,
            "app.main",
            &[],
            &interpreter::InterpreterOptions::default(),
        )
        .unwrap();
        assert!(!failed.returned);
        let envelope: serde_json::Value = serde_json::from_str(&failed.envelope).unwrap();
        assert_eq!(
            envelope["payload"]["outcome"]["status"]["domain_id"],
            "semaprax.contract.v1"
        );
        assert_eq!(envelope["payload"]["outcome"]["status"]["code"], 1);
    }

    let success_c = root.join("success.c");
    let failure_c = root.join("failure.c");
    std::fs::write(&success_c, codegen::emit_c(&program).unwrap()).unwrap();
    std::fs::write(&failure_c, codegen::emit_c(&failure).unwrap()).unwrap();
    for optimization in ["-O0", "-O2"] {
        for (source, binary) in [(&success_c, "success"), (&failure_c, "failure")] {
            let binary = root.join(format!("{binary}-{optimization}"));
            let compiled = Command::new("clang")
                .args(["-std=c11", "-Wall", "-Wextra", "-Werror", optimization])
                .arg(source)
                .arg("-o")
                .arg(&binary)
                .output()
                .unwrap();
            assert!(
                compiled.status.success(),
                "{optimization}: {}",
                String::from_utf8_lossy(&compiled.stderr)
            );
        }
        for _ in 0..4 {
            let output = Command::new(root.join(format!("success-{optimization}")))
                .output()
                .unwrap();
            assert!(output.status.success(), "success/{optimization}");
            assert_eq!(
                String::from_utf8_lossy(&output.stdout).trim(),
                expected.to_string()
            );
            let output = Command::new(root.join(format!("failure-{optimization}")))
                .output()
                .unwrap();
            assert_eq!(output.status.code(), Some(70), "failure/{optimization}");
            assert!(String::from_utf8_lossy(&output.stderr)
                .contains("requires byte != 9u8 in app.failure.reject"));
        }
    }

    // The complete fixture selects aggregate byte-data lowering. The legacy
    // scalar Web package deliberately has no String runtime; retain its refusal
    // rather than adding an authored aggregate merely to change that selector.
    let refused = semaprax::wasm::build_web(&program, &root.join("legacy-string")).unwrap_err();
    assert_eq!(refused.code, "SPX-W116");
    for (name, program, value) in [("success", &program, expected), ("failure", &failure, 0)] {
        let module = semaprax::wasm::emit_module(program).unwrap();
        raw_wasm(&root, name, &module, value);
    }
    let _ = std::fs::remove_dir_all(&root);
}

#[test]
fn byte_for_view_traversal_materializes_no_buffer_on_core_wasm() {
    let program = parse(VIEW_ONLY, Path::new("byte-slice-traversal-view-only.spx")).unwrap();
    let module = semaprax::wasm::emit_module(&program).unwrap();
    assert_eq!(module, semaprax::wasm::emit_module(&program).unwrap());
    // Copy is a mandatory aggregate-byte ABI import, even when unused. Prove
    // that no current function body calls its actual imported function index.
    let mut copy = None;
    let mut imports = Vec::new();
    for payload in wasmparser::Parser::new(0).parse_all(&module) {
        if let wasmparser::Payload::ImportSection(section) = payload.unwrap() {
            for import in section.into_imports() {
                let import = import.unwrap();
                assert!(matches!(import.ty, wasmparser::TypeRef::Func(_)));
                assert_eq!(import.module, "env");
                if import.name == "spx_bytes_copy" {
                    assert!(copy.replace(imports.len() as u32).is_none());
                }
                imports.push(import.name.to_owned());
            }
        }
    }
    assert_eq!(
        imports,
        [
            "spx_add",
            "spx_sub",
            "spx_mul",
            "spx_div",
            "spx_rem",
            "spx_neg",
            "spx_contract_fail",
            "spx_bytes_copy",
            "spx_bytes_get",
            "spx_bytes_drop",
            "spx_bytes_as_slice"
        ]
    );
    let copy = copy.expect("mandatory aggregate byte copy import");
    for payload in wasmparser::Parser::new(0).parse_all(&module) {
        if let wasmparser::Payload::CodeSectionEntry(body) = payload.unwrap() {
            let mut operators = body.get_operators_reader().unwrap();
            while !operators.eof() {
                let operator = operators.read().unwrap();
                assert!(
                    !matches!(operator, wasmparser::Operator::Call { function_index } if function_index == copy)
                );
                assert!(!matches!(
                    operator,
                    wasmparser::Operator::MemoryCopy { .. }
                        | wasmparser::Operator::MemoryGrow { .. }
                ));
            }
        }
    }
    let root = std::env::temp_dir().join(format!("semaprax-byte-for-view-{}", std::process::id()));
    std::fs::create_dir_all(&root).unwrap();
    raw_wasm(&root, "view", &module, 6);
    std::fs::remove_dir_all(root).unwrap();
}

/// Compare literal-slot reuse with an independently authored block-result
/// Copy boundary. Assignments and nested results retain their existing copy.
#[test]
fn literal_array_bindings_reuse_exact_slots_while_nonliteral_copy_boundaries_remain() {
    let root = std::env::temp_dir().join(format!(
        "semaprax-byte-literal-slots-{}",
        std::process::id()
    ));
    std::fs::create_dir_all(&root).unwrap();
    let header = &VIEW_ONLY[..VIEW_ONLY.find("@id(\"app.main\")").unwrap()];
    let copies = |module: &[u8]| {
        let mut copies = 0;
        for payload in wasmparser::Parser::new(0).parse_all(module) {
            if let wasmparser::Payload::CodeSectionEntry(body) = payload.unwrap() {
                let mut operators = body.get_operators_reader().unwrap();
                while !operators.eof() {
                    match operators.read().unwrap() {
                        wasmparser::Operator::MemoryCopy { .. } => copies += 1,
                        wasmparser::Operator::MemoryGrow { .. } => {
                            panic!("fixed array grew memory")
                        }
                        _ => {}
                    }
                }
            }
        }
        copies
    };
    for (ordinal, literal, expected) in [
        (0, "[]", 0),
        (1, "[7u8]", 7),
        (2, "[1u8, 2u8, 3u8]", 6),
        (3, "[1u8; 256]", 256),
    ] {
        for old in [false, true] {
            let initializer = if old {
                format!("{{let pad = 0; {literal}}}")
            } else {
                literal.to_owned()
            };
            let source = format!("{header}@id(\"app.main\") fn main()->i64 {{ let data = {initializer}; sum(array_as_slice(data)) }}");
            let path = root.join(format!("literal-{ordinal}-{old}.spx"));
            std::fs::write(&path, &source).unwrap();
            let program = parse(&source, &path).unwrap();
            let resolved = hir::resolve(&program).unwrap();
            hir::validate(&resolved).unwrap();
            let outcome = interpreter::interpret(
                &path,
                "app.main",
                &[],
                &interpreter::InterpreterOptions::default(),
            )
            .unwrap();
            assert!(outcome.returned, "{}", outcome.envelope);
            assert!(
                outcome
                    .envelope
                    .contains(&format!("\"value\":\"{expected}\"")),
                "{}",
                outcome.envelope
            );
            let module = semaprax::wasm::emit_module(&program).unwrap();
            assert_eq!(module, semaprax::wasm::emit_module(&program).unwrap());
            if old && ordinal != 0 {
                assert!(copies(&module) > 0);
            } else {
                assert_eq!(copies(&module), 0);
            }
            raw_wasm(&root, "view", &module, expected);
        }
    }
    // A normally completing preceding call stays before initialization. A
    // later failed precondition keeps the original full-engine failure owner.
    let source = format!("{header}@id(\"app.touch\") fn touch()->i64 {{1}} @id(\"app.main\") fn main()->i64 {{ let mark = touch(); let mut data = [1u8]; data = [7u8]; mark + sum(array_as_slice(data)) }}");
    let path = root.join("assignment.spx");
    std::fs::write(&path, &source).unwrap();
    let program = parse(&source, &path).unwrap();
    let errors = hir::resolve(&program).expect_err("array assignment must stay unadmitted");
    assert!(
        errors.iter().any(|error| error.code == "SPX-U105"),
        "{errors:?}"
    );
    // Repeated calls reinitialize the same function-frame slots. Keep array
    // mutation and loop-local literals as explicit negative controls.
    for old in [false, true] {
        let initializer = if old {
            "{ let pad = 0; [7u8] }"
        } else {
            "[7u8]"
        };
        let source = format!("{header}@id(\"app.main\") fn main()->i64 {{ let mut index = 0; let mut total = 0; while index < 3 {{ let mut data = {initializer}; let first = sum(array_as_slice(data)); data = [9u8]; total = total + first + sum(array_as_slice(data)); index = index + 1; 0 }} total }}");
        let rejected_path = root.join(format!("loop-local-array-{old}.spx"));
        let rejected = parse(&source, &rejected_path).unwrap();
        let errors = match hir::resolve(&rejected) {
            Ok(_) => panic!("loop-local array literals unexpectedly admitted"),
            Err(errors) => errors,
        };
        let diagnostic = format!("{errors:?}");
        assert!(diagnostic.contains("SPX-T252"), "{diagnostic}");
        assert!(
            diagnostic.contains("fixed-array literals are not admitted in bounded while bodies"),
            "{diagnostic}"
        );
        let source = format!("{header}@id(\"app.sample\") fn sample()->i64 {{ let data = {initializer}; let first = sum(array_as_slice(data)); let other = [9u8]; first + sum(array_as_slice(other)) }} @id(\"app.main\") fn main()->i64 {{ sample() + sample() + sample() }}");
        let path = root.join(format!("reinitialize-{old}.spx"));
        std::fs::write(&path, &source).unwrap();
        let program = parse(&source, &path).unwrap();
        let resolved = hir::resolve(&program).unwrap();
        hir::validate(&resolved).unwrap();
        let outcome = interpreter::interpret(
            &path,
            "app.main",
            &[],
            &interpreter::InterpreterOptions::default(),
        )
        .unwrap();
        let expected = 3 * (7 + 9);
        assert!(outcome.returned, "{}", outcome.envelope);
        assert!(
            outcome
                .envelope
                .contains(&format!("\"value\":\"{expected}\"")),
            "{}",
            outcome.envelope
        );
        let module = semaprax::wasm::emit_module(&program).unwrap();
        assert_eq!(module, semaprax::wasm::emit_module(&program).unwrap());
